+/// Divides the nonzero `u` by its largest power of two `2^t`, and replaces
+/// the canonical cofactor `x` by `x / 2^t mod n`.
+#[inline(always)]
+fn remove_twos(u: &mut [u64; 4], x: &mut [u64; 4]) {
