+/// Shifts the five-limb value `a, top` right by `t` bits, `1 <= t <= 63`.
+#[inline(always)]
+fn shr_bits(a: [u64; 4], top: u64, t: u32) -> [u64; 4] {
+    [
+        (a[0] >> t) | (a[1] << (64 - t)),
+        (a[1] >> t) | (a[2] << (64 - t)),
+        (a[2] >> t) | (a[3] << (64 - t)),
+        (a[3] >> t) | (top << (64 - t)),
+    ]
