+/// Divides the nonzero `u` by its largest power of two, halving the canonical
+/// cofactor `x` modulo n once per removed bit.
+#[inline(always)]
+fn remove_twos(u: &mut [u64; 4], x: &mut [u64; 4]) {
+    while u[0] & 1 == 0 {
+        *u = shr1(*u, 0);
+        *x = half_mod(*x);
+    }
+}
+
+#[inline(always)]
+fn shr1(a: [u64; 4], top: u64) -> [u64; 4] {
+    [
+        (a[0] >> 1) | (a[1] << 63),
+        (a[1] >> 1) | (a[2] << 63),
+        (a[2] >> 1) | (a[3] << 63),
+        (a[3] >> 1) | (top << 63),
+    ]
+}
+
+#[inline(always)]
+fn half_mod(a: [u64; 4]) -> [u64; 4] {
+    if a[0] & 1 == 0 {
+        shr1(a, 0)
+    } else {
+        let (sum, carry) = add_limbs(a, MODULUS);
+        shr1(sum, carry)
+    }
+}
